begin;
select no_plan();
insert into auth.users(id) values ('c0110000-0000-0000-0000-000000000001'),('c0110000-0000-0000-0000-000000000002');
insert into public.profiles values ('c0110000-0000-0000-0000-000000000001','owner'),('c0110000-0000-0000-0000-000000000002','driver');
select set_config('request.jwt.claim.sub','c0110000-0000-0000-0000-000000000001',true);
set local role authenticated;
select lives_ok($$select public.save_customer('c0110000-0000-0000-0000-000000000003',0,'{"name":"Cadastro fictício pendente","address":"Rua fictícia, 7","phone":null,"active":false,"weekday":null,"position":7,"notes":"Entregar na portaria. <script>literal</script>","reviewPending":true}','[]','[]','c0110000-0000-0000-0000-000000000004')$$,'cadastro pendente preserva observação sem inventar dia');
select is((select notes from public.customers where id='c0110000-0000-0000-0000-000000000003'),'Entregar na portaria. <script>literal</script>','observação preservada como texto');
select ok((select weekday is null and not active and review_pending from public.customers where id='c0110000-0000-0000-0000-000000000003'),'pendência não participa da operação');
select throws_ok($$select public.save_customer('c0110000-0000-0000-0000-000000000003',1,'{"name":"Cadastro fictício pendente","address":"Rua fictícia, 7","active":true,"weekday":4,"position":7,"reviewPending":true}','[]','[]',gen_random_uuid())$$,'22023','INVALID_INPUT','não ativa sem conferir');
select throws_ok($$select public.save_customer(gen_random_uuid(),0,'{"name":"Sem dia","address":"Rua fictícia","active":true,"weekday":null,"position":1,"reviewPending":false}','[]','[]',gen_random_uuid())$$,'22023','INVALID_INPUT','cliente ativo exige dia');
select lives_ok($$select public.save_customer('c0110000-0000-0000-0000-000000000003',1,'{"name":"Cadastro fictício pendente","address":"Rua corrigida","active":false,"weekday":null,"position":7,"notes":"Observação atualizada","reviewPending":true}','[]','[]','c0110000-0000-0000-0000-000000000005')$$,'edita contato e observação enquanto confere');
select lives_ok($$select public.save_customer('c0110000-0000-0000-0000-000000000003',0,'{"name":"Cadastro fictício pendente","address":"Rua fictícia, 7","phone":null,"active":false,"weekday":null,"position":7,"notes":"Entregar na portaria. <script>literal</script>","reviewPending":true}','[]','[]','c0110000-0000-0000-0000-000000000004')$$,'replay antigo retorna resultado sem sobrescrever');
select is((select notes from public.customers where id='c0110000-0000-0000-0000-000000000003'),'Observação atualizada','replay não reverte observação');
select throws_ok($$select public.save_customer('c0110000-0000-0000-0000-000000000003',1,'{"name":"Conflito","address":"Rua fictícia","active":false,"weekday":null,"position":7,"reviewPending":true}','[]','[]',gen_random_uuid())$$,'PT409','VERSION_CONFLICT','versão antiga continua protegida');
select throws_ok($$select public.save_customer(gen_random_uuid(),0,jsonb_build_object('name','Muito texto','address','Rua fictícia','active',false,'weekday',null,'position',1,'reviewPending',true,'notes',repeat('a',10001)),'[]','[]',gen_random_uuid())$$,'22023','INVALID_INPUT','observação tem limite de tamanho');
reset role;
update public.customers set source_details='{"row":7,"cells":{"C":"X","N":"SEGUNDA","K":"Nota original"}}' where id='c0110000-0000-0000-0000-000000000003';
set local role authenticated;
select lives_ok($$select public.save_customer('c0110000-0000-0000-0000-000000000003',2,'{"name":"Cadastro fictício conferido","address":"Rua corrigida","active":true,"weekday":4,"position":7,"notes":"Observação conferida","reviewPending":false}','[]','[]',gen_random_uuid())$$,'cadastro pode ser conferido e ativado explicitamente');
select is((select source_details->>'row' from public.customers where id='c0110000-0000-0000-0000-000000000003'),'7','edição preserva referência à origem');
select lives_ok($$select public.save_customer('c0110000-0000-0000-0000-000000000003',3,'{"name":"Cliente legado","address":"Rua corrigida","active":true,"weekday":4,"position":7}','[]','[]',gen_random_uuid())$$,'payload legado continua válido');
select is((select notes from public.customers where id='c0110000-0000-0000-0000-000000000003'),'Observação conferida','payload legado não apaga observação');
reset role;
select set_config('request.jwt.claim.sub','c0110000-0000-0000-0000-000000000002',true);
set local role authenticated;
select is((select count(*) from public.customers where id='c0110000-0000-0000-0000-000000000003'),0::bigint,'motorista não lê dados administrativos');
select throws_ok($$select public.save_customer(gen_random_uuid(),0,'{}','[]','[]',gen_random_uuid())$$,'42501','FORBIDDEN','motorista não altera cadastro');
reset role;
set local role anon;
select throws_ok('select notes,source_details from public.customers','42501',null,'anônimo não acessa observações ou origem');
reset role;
select * from finish();
rollback;
